<?php use app\services\Ui;use yii\helpers\Html;$this->title='Universitet tuzilmasi';$v=fn($key,$default='')=>Yii::$app->request->post($key,$edit[$key]??$default);$kinds=['university'=>'Universitet','faculty'=>'Fakultet','department'=>'Kafedra']; ?>
<div class="page-heading"><div><span class="eyebrow">ADMINISTRATOR</span><h1>Universitet tuzilmasi</h1><p>Universitet → fakultet → kafedra tartibida yarating.</p></div></div><section class="card"><h2><?= $edit?'Bo‘limni tahrirlash':'Yangi bo‘lim' ?></h2><?= Html::beginForm(['admin/structure','id'=>$edit['id']??null],'post',['class'=>'filters']) ?><?= Ui::input('Nomi','name',$v('name'),'text',['required'=>true,'maxlength'=>200]) ?><?= Ui::select('Turi','kind',$v('kind','faculty'),$kinds) ?><?= Ui::select('Yuqori bo‘lim','parent_id',$v('parent_id'),[''=>'Yo‘q (universitet uchun)']+array_column($rows,'name','id')) ?><button class="button">Saqlash</button><?= Html::endForm() ?></section><section class="card"><h2>Bo‘limlar</h2><div class="table-wrap"><table><thead><tr><th>Nomi</th><th>Turi</th><th>Yuqori bo‘lim</th><th></th></tr></thead><tbody><?php $names=array_column($rows,'name','id');foreach($rows as $row): ?><tr><td><b><?= Ui::h($row['name']) ?></b></td><td><?= Ui::h($kinds[$row['kind']]) ?></td><td><?= Ui::h($names[$row['parent_id']]??'—') ?></td><td><?= Html::a('Tahrirlash',['admin/structure','id'=>$row['id']],['class'=>'text-link']) ?></td></tr><?php endforeach ?></tbody></table></div></section>
